-- Catalog-only PostgreSQL18 inspection. No application rows, credentials or
-- function bodies. Run only with an existing owner-authorized observation route.
-- Use PGOPTIONS for timeouts/default_transaction_read_only and TLS verify-full.
\set QUIET on
BEGIN READ ONLY;
SELECT jsonb_build_object(
 'transactionReadOnly',current_setting('transaction_read_only'),
 'defaultTransactionReadOnly',current_setting('default_transaction_read_only'),
 'serverMajor',current_setting('server_version_num')::int / 10000,
 'role', (SELECT jsonb_build_object('superuser',rolsuper,'createRole',rolcreaterole,'createDatabase',rolcreatedb,'replication',rolreplication,'bypassRls',rolbypassrls,'inherit',rolinherit,'login',rolcanlogin) FROM pg_catalog.pg_roles WHERE rolname=current_user),
 'database', (SELECT jsonb_build_object('currentRoleOwns',datdba=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user),'inheritsOwner',pg_has_role(current_user,datdba,'USAGE'),'canSetOwnerRole',pg_has_role(current_user,datdba,'SET'),'canCreateSchema',has_database_privilege(current_user,oid,'CREATE'),'canCreateTemporary',has_database_privilege(current_user,oid,'TEMPORARY')) FROM pg_catalog.pg_database WHERE datname=current_database()),
 'publicSchema', (SELECT jsonb_build_object('currentRoleOwns',nspowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user),'inheritsOwner',pg_has_role(current_user,nspowner,'USAGE'),'canSetOwnerRole',pg_has_role(current_user,nspowner,'SET'),'create',has_schema_privilege(current_user,oid,'CREATE'),'usage',has_schema_privilege(current_user,oid,'USAGE')) FROM pg_catalog.pg_namespace WHERE nspname='public'),
 'publicTables',(SELECT jsonb_build_object('count',count(*),'ownedByCurrentRole',count(*) FILTER(WHERE relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user)),'ownerPrivilegeInherited',count(*) FILTER(WHERE pg_has_role(current_user,relowner,'USAGE')),'ownerRoleSettable',count(*) FILTER(WHERE pg_has_role(current_user,relowner,'SET')),'rlsEnabled',count(*) FILTER(WHERE relrowsecurity),'forceRlsEnabled',count(*) FILTER(WHERE relforcerowsecurity)) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p')),
 'sensitiveTables', (SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'ownedByCurrentRole',c.relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user),'ownerRoleSettable',pg_has_role(current_user,c.relowner,'SET'),'select',has_table_privilege(current_user,c.oid,'SELECT'),'insert',has_table_privilege(current_user,c.oid,'INSERT'),'update',has_table_privilege(current_user,c.oid,'UPDATE'),'selectAnyColumn',has_any_column_privilege(current_user,c.oid,'SELECT'),'insertAnyColumn',has_any_column_privilege(current_user,c.oid,'INSERT'),'updateAnyColumn',has_any_column_privilege(current_user,c.oid,'UPDATE'),'delete',has_table_privilege(current_user,c.oid,'DELETE'),'truncate',has_table_privilege(current_user,c.oid,'TRUNCATE'),'trigger',has_table_privilege(current_user,c.oid,'TRIGGER'),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity)),'[]'::jsonb) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('__EFMigrationsHistory','AbpUsers','AbpRoles','AbpUserRoles','AbpPermissions','AbpTenants','AreaAdminAssignments','Customers','MemberPayments','EntryWeeklyCommissions','OnyxWeeklyCommissions','TransactionalEmailOutboxMessages','DataProtectionKeys')),
 'sensitiveColumns',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'select',has_column_privilege(current_user,c.oid,a.attnum,'SELECT'),'insert',has_column_privilege(current_user,c.oid,a.attnum,'INSERT'),'update',has_column_privilege(current_user,c.oid,a.attnum,'UPDATE'))),'[]'::jsonb) FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND a.attnum>0 AND NOT a.attisdropped AND ((c.relname='AbpUsers' AND a.attname IN ('Name','Password','SecurityStamp','EmailAddress','Role','TenantId','IsActive','IsDeleted')) OR (c.relname='Customers' AND a.attname IN ('TenantId','AreaId','MembershipId','UserId')) OR (c.relname='TransactionalEmailOutboxMessages' AND a.attname IN ('TenantId','Recipient','Status','ProviderMessageId','SentAt','AttemptCount')))),
 'otherLoginRoles',(SELECT count(*) FROM pg_catalog.pg_roles WHERE rolcanlogin AND rolname<>current_user),
 'reachableDangerousRoles',(SELECT coalesce(jsonb_agg(jsonb_build_object('builtInName',CASE WHEN rolname ~ '^(pg_|postgres$|render_superuser$)' THEN rolname ELSE 'OTHER_ROLE' END,'inherit',pg_has_role(current_user,oid,'USAGE'),'set',pg_has_role(current_user,oid,'SET'),'superuser',rolsuper,'createRole',rolcreaterole,'createDatabase',rolcreatedb,'replication',rolreplication,'bypassRls',rolbypassrls)),'[]'::jsonb) FROM pg_catalog.pg_roles WHERE rolname<>current_user AND (rolsuper OR rolcreaterole OR rolcreatedb OR rolreplication OR rolbypassrls OR rolname IN ('pg_read_server_files','pg_write_server_files','pg_execute_server_program')) AND (pg_has_role(current_user,oid,'USAGE') OR pg_has_role(current_user,oid,'SET'))),
 'userSchemas',(SELECT jsonb_build_object('total',count(*),'creatable',count(*) FILTER(WHERE has_schema_privilege(current_user,oid,'CREATE'))) FROM pg_catalog.pg_namespace WHERE nspname !~ '^pg_' AND nspname<>'information_schema'),
 'userSecurityDefinerFunctions',(SELECT jsonb_build_object('total',count(*),'executable',count(*) FILTER(WHERE has_function_privilege(current_user,p.oid,'EXECUTE'))) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema' AND p.prosecdef),
 'publicSecurityDefinerFunctions',(SELECT jsonb_build_object('total',count(*),'executable',count(*) FILTER(WHERE has_function_privilege(current_user,p.oid,'EXECUTE'))) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prosecdef),
 'roleAdministrationMemberships',(SELECT count(*) FROM pg_catalog.pg_auth_members WHERE member=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user) AND admin_option)
);
ROLLBACK;
